reference_solution:
def can_remove_ones_by_flips(grid):
    first=grid[0]
    for row in grid[1:]:
        same=all(a==b for a,b in zip(row,first));opposite=all(a!=b for a,b in zip(row,first))
        if not (same or opposite):return False
    return True

